func (this *HollaexCore) ParseTransaction(transaction any, optionalArgs ...any) any {
	//
	// fetchWithdrawals, fetchDeposits
	//
	//     {
	//         "id": 539,
	//         "amount": 20,
	//         "fee": 0,
	//         "address": "0x5c0cc98270d7089408fcbcc8e2131287f5be2306",
	//         "transaction_id": "0xd4006327a5ec2c41adbdcf566eaaba6597c3d45906abe78ea1a4a022647c2e28",
	//         "status": true,
	//         "dismissed": false,
	//         "rejected": false,
	//         "description": "",
	//         "type": "withdrawal",
	//         "currency": "usdt",
	//         "created_at": "2020-03-03T07:56:36.198Z",
	//         "updated_at": "2020-03-03T08:00:05.674Z",
	//         "user_id": 620
	//     }
	//
	// withdraw
	//
	//     {
	//         "message": "Withdrawal request is in the queue and will be processed.",
	//         "transaction_id": "1d1683c3-576a-4d53-8ff5-27c93fd9758a",
	//         "amount": 1,
	//         "currency": "xht",
	//         "fee": 0,
	//         "fee_coin": "xht"
	//     }
	//
	currency := GetArg(optionalArgs, 0, nil)
	_ = currency
	var id *string = this.SafeString(transaction, "id")
	var txid *string = this.SafeString(transaction, "transaction_id")
	var timestamp any = this.Parse8601(this.SafeString(transaction, "created_at"))
	var updated any = this.Parse8601(this.SafeString(transaction, "updated_at"))
	var typeVar *string = this.SafeString(transaction, "type")
	var amount any = this.SafeNumber(transaction, "amount")
	var address *string = this.SafeString(transaction, "address")
	var addressTo any = nil
	var addressFrom any = nil
	var tag any = nil
	var tagTo any = nil
	var tagFrom any = nil
	if address != nil {
		var parts []string = Split(address, ":")
		address = this.SafeString(parts, 0)
		tag = this.SafeString(parts, 1)
		addressTo = address
		tagTo = tag
	}
	var currencyId *string = this.SafeString(transaction, "currency")
	currency = this.SafeCurrency(currencyId, currency)
	var status any = this.SafeValue(transaction, "status")
	var dismissed any = this.SafeValue(transaction, "dismissed")
	var rejected any = this.SafeValue(transaction, "rejected")
	if EvalTruthy(status) {
		status = "ok"
	} else if EvalTruthy(dismissed) {
		status = "canceled"
	} else if EvalTruthy(rejected) {
		status = "failed"
	} else {
		status = "pending"
	}
	var feeCurrencyId *string = this.SafeString(transaction, "fee_coin")
	var feeCurrencyCode any = this.SafeCurrencyCode(feeCurrencyId, currency)
	var feeCost any = this.SafeNumber(transaction, "fee")
	var fee any = nil
	if !IsEqual(feeCost, nil) {
		fee = map[string]any{
			"currency": feeCurrencyCode,
			"cost":     feeCost,
		}
	}
	return map[string]any{
		"info":        transaction,
		"id":          id,
		"txid":        txid,
		"timestamp":   timestamp,
		"datetime":    this.Iso8601(timestamp),
		"network":     nil,
		"addressFrom": addressFrom,
		"address":     address,
		"addressTo":   addressTo,
		"tagFrom":     tagFrom,
		"tag":         tag,
		"tagTo":       tagTo,
		"type":        typeVar,
		"amount":      amount,
		"currency":    GetValue(currency, "code"),
		"status":      status,
		"updated":     updated,
		"comment":     this.SafeString(transaction, "message"),
		"internal":    nil,
		"fee":         fee,
	}
}

/**
 * @method
 * @name hollaex#withdraw
 * @description make a withdrawal
 * @see https://apidocs.hollaex.com/#withdrawal
 * @param {string} code unified currency code
 * @param {float} amount the amount to withdraw
 * @param {string} address the address to withdraw to
 * @param {string} tag
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [transaction structure]{@link https://docs.ccxt.com/?id=transaction-structure}
 */
func (this *HollaexCore) Withdraw(code any, amount any, address any, optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.withdrawBody(ch, code, amount, address, optionalArgs...)
	return ch
}
func (this *HollaexCore) withdrawBody(ch chan any, code any, amount any, address any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	tag := GetArg(optionalArgs, 0, nil)
	_ = tag
	params := GetArg(optionalArgs, 1, map[string]any{})
	_ = params
	tagparamsVariable := this.HandleWithdrawTagAndParams(tag, params)
	tag = GetValue(tagparamsVariable, 0)
	params = GetValue(tagparamsVariable, 1)
	this.CheckAddress(address)
	if IsEqual(this.Markets, nil) {

		retRes191712 := (<-this.LoadMarkets())
		PanicOnError(retRes191712)
	}
	var currency any = this.Currency(code)
	if !IsEqual(tag, nil) {
		address = Add(address, Add(":", tag))
	}
	var network *string = this.SafeString(params, "network")
	if network == nil {
		panic(ArgumentsRequired(Add(this.Id, " withdraw() requires a network parameter")))
	}
	params = this.Omit(params, "network")
	var request map[string]any = map[string]any{
		"currency": GetValue(currency, "id"),
		"amount":   amount,
		"address":  address,
		"network":  this.NetworkCodeToId(network, code),
	}

	response := (<-this.PrivatePostUserWithdrawal(this.Extend(request, params)))
	PanicOnError(response)

	//
	//     {
	//         "message": "Withdrawal request is in the queue and will be processed.",
	//         "transaction_id": "1d1683c3-576a-4d53-8ff5-27c93fd9758a",
	//         "amount": 1,
	//         "currency": "xht",
	//         "fee": 0,
	//         "fee_coin": "xht"
	//     }
	//
	ch <- this.ParseTransaction(response, currency)
	return nil
}
func (this *HollaexCore) ParseDepositWithdrawFee(fee any, optionalArgs ...any) any {
	//
	//    "bch":{
	//        "id":4,
	//        "fullname":"Bitcoin Cash",
	//        "symbol":"bch",
	//        "active":true,
	//        "verified":true,
	//        "allow_deposit":true,
	//        "allow_withdrawal":true,
	//        "withdrawal_fee":0.0001,
	//        "min":0.001,
	//        "max":100000,
	//        "increment_unit":0.001,
	//        "logo":"https://bitholla.s3.ap-northeast-2.amazonaws.com/icon/BCH-hollaex-asset-01.svg",
	//        "code":"bch",
	//        "is_public":true,
	//        "meta":{},
	//        "estimated_price":null,
	//        "description":null,
	//        "type":"blockchain",
	//        "network":null,
	//        "standard":null,
	//        "issuer":"HollaEx",
	//        "withdrawal_fees":null,
	//        "created_at":"2019-08-09T10:45:43.367Z",
	//        "updated_at":"2021-12-13T03:08:32.372Z",
	//        "created_by":1,
	//        "owner_id":1
	//    }
	//
	currency := GetArg(optionalArgs, 0, nil)
	_ = currency
	var result map[string]any = map[string]any{
		"info": fee,
		"withdraw": map[string]any{
			"fee":        nil,
			"percentage": nil,
		},
		"deposit": map[string]any{
			"fee":        nil,
			"percentage": nil,
		},
		"networks": map[string]any{},
	}
	var allowWithdrawal any = this.SafeValue(fee, "allow_withdrawal")
	if EvalTruthy(allowWithdrawal) {
		AddElementToObject(result, "withdraw", map[string]any{
			"fee":        this.SafeNumber(fee, "withdrawal_fee"),
			"percentage": false,
		})
	}
	var withdrawalFees any = this.SafeValue(fee, "withdrawal_fees")
	if !IsEqual(withdrawalFees, nil) {
		var keys []string = ObjectKeys(withdrawalFees)
		var keysLength int = GetArrayLength(keys)
		for i := 0; IsLessThan(i, keysLength); i++ {
			var key any = GetValue(keys, i)
			var value any = GetValue(withdrawalFees, key)
			var currencyId *string = this.SafeString(value, "symbol")
			var currencyCode any = this.SafeCurrencyCode(currencyId)
			var networkCode any = this.NetworkIdToCode(key, currencyCode)
			if IsEqual(networkCode, nil) {
				panic(ArgumentsRequired(Add(this.Id, " requires a networkCode argument")))
			}
			var networkCodeUpper string = ToUpper(networkCode) // default to the upper case network code
			var withdrawalFee any = this.SafeNumber(value, "value")
			AddElementToObject(GetValue(result, "networks"), networkCodeUpper, map[string]any{
				"deposit":  nil,
				"withdraw": withdrawalFee,
			})
		}
	}
	return result
}

